from typing import List

def solve_tsp(distances: List[List[int]]) -> int:
    n = len(distances)
    # dp[i][mask] will store the minimum weight Hamiltonian Cycle
    dp = [[0 for _ in range(1 << n)] for _ in range(n)]
    for i in range(n):
        dp[i][(1 << i)] = float('inf')

    for mask in range(1, 1 << n):
        for bit in range(n):
            if (mask & (1 << bit)):
                for prev in range(n):
                    if prev != bit and (mask & (1 << prev)):
                        # if the bit is on, consider this city
                        dp[bit][mask] = min(dp[bit][mask], distances[prev][bit] + dp[prev][mask ^ (1 << bit)])

    # find the minimum weight Hamiltonian Cycle
    answer = float('inf')
    for i in range(n):
        answer = min(answer, dp[i][(1 << n) - 1])

    return answer

