        for j in range(1, max_hours + 1):
            profit1 = dp[i - m1][j - h1] + p1 if i >= m1 and j >= h1 else -1
            profit2 = dp[i - m2][j - h2] + p2 if i >= m2 and j >= h2 else -1
            dp[i][j] = max(profit1, profit2)
