def calculate_probability_score(n: int, k: int, r: int, p: int, s: int) -> float:
    """
    Calculate the probability of getting exactly 's' points out of 'n' points.
    """
    if s < 0 or s > n:
        raise ValueError("Score must be between 0 and number of questions.")
    if k < 1:
        raise ValueError("Number of options per question must be at least 1.")
    if r < 0 or r > k:
        raise ValueError("Correct answer must be between 0 and number of options.")
    if p < -1 or p > 1:
        raise ValueError("Probability of correct answer must be between -1 and 1.")

