def count_grid_ways(nums: List[int]) -> int:
    # Sort the numbers
    nums.sort()

    # Initialize the dp table
    dp = [[[0 for _ in range(85)] for _ in range(85)] for _ in range(85)]
    dp[0][0][0] = 1

    # Fill the dp table
    for i in range(len(nums) + 1):
        for j in range(i + 1):
            for k in range(j + 1):
                if i:
                    dp[i][j][k] += dp[i-1][j][k]
                if j:
                    dp[i][j][k] += dp[i][j-1][k]
                if k:
                    dp[i][j][k] += dp[i][j][k-1]
                if i and j:
                    dp[i][j][k] += dp[i-1][j-1][k]
                if i and k:
                    dp[i][j][k] += dp[i-1][j][k-1]
                if j and k:
                    dp[i][j][k] += dp[i][j-1][k-1]
                if i and j and k:
                    dp[i][j][k] += dp[i-1][j-1][k-1]

    # Count the ways
    ways = 0
    for i in range(1, len(nums) + 1):
        if i % 3 == 0 and i // 3 <= 10:
