def count_grid_ways(nums: List[int]) -> int:
    total = sum(nums)
    if total % 3 != 0:
        return 0

    target = total // 3
    dp, dp2 = [0] * (target + 1), [0] * (target + 1)
    dp[0] = 1

    for num in nums:
        for i in range(target, num - 1, -1):
            dp2[i] = dp2[i - num] + dp[i]
            if i >= num:
                dp[i] = dp[i - num] + dp[i]

    return dp2[target] * comb(3, 2)

