def calculate_grouped_std(intervals, frequencies):
    mean = sum(freq * (start + end) / 2 for (start, end), freq in zip(intervals, frequencies)) / sum(frequencies)
    std_dev = sum(freq * ((start + end) / 2 - mean) ** 2 for (start, end), freq in zip(intervals, frequencies)) / sum(frequencies)
    return round(std_dev ** 0.5, 2)

