    left, right = total_debt // months, total_debt
    while left < right:
        mid = (left + right) // 2
        if check(mid, total_debt, target_percentage, months, decay_ratio):
            right = mid
        else:
            left = mid + 1
    return left

def check(first_payment, total_debt, target_percentage, months, decay_ratio):
    remaining = total_debt
    for _ in range(months):
        remaining = max(0, remaining - first_payment)
        remaining *= decay_ratio
    return remaining <= total_debt * target_percentage
